      "text": [
       {
        "_type": "block",
        "style": "normal",
        "children": [
         {
          "_type": "span",
          "text": "Curious pets and small children are especially vulnerable if they come into contact with nesting bats or contaminated areas.",
          "marks": []
         }
        ],
        "markDefs": []
       }
      ],
