    "heading": "Health Risks",
    "variant": "plain",
    "columns": 3,
    "cards": [
     {
      "title": "Venomous Snakebites",
      "text": [
       {
        "_type": "block",
        "style": "normal",
        "children": [
         {
          "_type": "span",
          "text": "Tampa is home to several venomous species, including Eastern Diamondback Rattlesnakes, Water Moccasins (Cottonmouths), Coral Snakes, and Pygmy Rattlesnakes. Bites from these species can cause severe injury or even death if not treated immediately.",
          "marks": []
         }
        ],
        "markDefs": []
       }
      ],
      "href": "/about-us/service-area/wildlife-removal-hillsborough-county/"
     },
     {
      "title": "Secondary Infections",
      "text": [
       {
        "_type": "block",
        "style": "normal",
        "children": [
         {
          "_type": "span",
          "text": "Even non-venomous snake bites can become infected if untreated, potentially leading to serious medical complications.",
          "marks": []
         }
        ],
        "markDefs": []
       }
      ],
      "href": "/about-us/service-area/wildlife-removal-hillsborough-county/"
     },
     {
      "title": "Emotional Stress & Safety Concerns",
      "text": [
       {
        "_type": "block",
        "style": "normal",
        "children": [
         {
          "_type": "span",
          "text": "For many homeowners, the simple presence of snakes creates anxiety, fear, and ongoing stress, especially in households with children or pets.",
          "marks": []
         }
        ],
        "markDefs": []
       }
      ],
      "href": "/about-us/service-area/wildlife-removal-hillsborough-county/"
     }
    ],
