        "text": "Average adult length is 2-3 feet. Have very thick bodies and are light-brown to grey in color. Have large, dark-brown bands in the shape of an hourglass that run down the length of the body. If you have encountered a snake on your home property and aren’t sure if it’s poisonous or not, give the certified Snake removal Central Florida professionals at Pro Wildlife Removal a call. Our trained and licensed staff will arrive quickly to safely remove the snake.",
